-- Minimal WebRTC Setup (One command)
-- Just run this single command in Supabase SQL Editor:

CREATE TABLE IF NOT EXISTS public.session_participants (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, session_id UUID REFERENCES public.live_sessions(id) ON DELETE CASCADE, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, name TEXT NOT NULL, is_host BOOLEAN DEFAULT false, is_muted BOOLEAN DEFAULT false, is_video_off BOOLEAN DEFAULT false, joined_at TIMESTAMPTZ DEFAULT now(), UNIQUE(session_id, user_id)); ALTER TABLE public.session_participants ENABLE ROW LEVEL SECURITY; DO $$ BEGIN DROP POLICY IF EXISTS "sp_select" ON public.session_participants; DROP POLICY IF EXISTS "sp_insert" ON public.session_participants; DROP POLICY IF EXISTS "sp_update" ON public.session_participants; DROP POLICY IF EXISTS "sp_delete" ON public.session_participants; EXECUTE 'CREATE POLICY "sp_select" ON public.session_participants FOR SELECT USING (true)'; EXECUTE 'CREATE POLICY "sp_insert" ON public.session_participants FOR INSERT WITH CHECK (auth.uid() = user_id)'; EXECUTE 'CREATE POLICY "sp_update" ON public.session_participants FOR UPDATE USING (auth.uid() = user_id)'; EXECUTE 'CREATE POLICY "sp_delete" ON public.session_participants FOR DELETE USING (auth.uid() = user_id)'; EXCEPTION WHEN OTHERS THEN NULL; END $$; DO $$ BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE public.session_participants; EXCEPTION WHEN duplicate_object THEN NULL; END $$; SELECT 'WebRTC ready!' as status;